#pragma once

#include <stddef.h>
#include <stdint.h>

/* Material Design Icons name -> codepoint, sorted by name (strcmp order).
 * Generated by tools/gen_mdi_names.py. */
typedef struct {
    const char *name;
    uint32_t codepoint;
} mdi_name_entry_t;

extern const mdi_name_entry_t g_mdi_names[];
extern const size_t g_mdi_names_count;
